event.script:
var a = xfa.layout.page(this).toString();

//Check the length of the page number. If it is two digits increase the datalength of the barcode by 1
if (a.length == 2)
{
	this.ui.oneOfChild.dataLength = "18";	
}

this.rawValue = FormID.value + Divider.value + RevDate.value + Divider.value + xfa.layout.page(this);

// allows A-Z, a-z, - and spaces
