	keyRegEx[12] = /[^0-9]/;
	keyRegEx[13] = /[^0-9\.]/;
	keyRegEx[14] = /[^A-Za-z0-9\.\,\''\-\&amp;\ ]/;
	keyRegEx[15] = /[^0-9\/]/; 
