	keyRegEx[23] = /[^a-zA-Z0-9\-\.\,\''\&]/;
	keyRegEx[24] = /[^0-9AaNnOoEe\/]/;
	keyRegEx[25] = /[^0-9DdSs\/]/;
	keyRegEx[26] = /[^0-9PpRrSsEeNnTt\/]/;


	valueRegEx[0] = /^[0-9]{9}$/;																	//9		| A-Number, US SSN, Fed Emp ID Number (FEIN)
