	valueRegEx[4] = /^[9]{1}[0-9]{2}[7-8]{1}[0-9]{5}$/; 												//3-9 	| Indiv Taxpayer ID Number (ITIN)
	valueRegEx[5] = /^[0-9]{9}[A-Z0-9]{1}[0-9]{1}$/;													//11 	| I-94 Arrival-Departure Record Num
	valueRegEx[6] = /^[ACIH0-5- ]{1,5}$/;																//1-5 	| LCA or ETA Case Number 
	valueRegEx[7] = /^[A-Z0-9]{5,16}$/;																//5-16 	| Passport Number
	valueRegEx[8] = /^RC[0-9]{10}$/;  																//12		| Regional Center Identification Number
	valueRegEx[9] = /^[A-Z]{3}[0-9*]{1}[0-9]{9}$/; 													//13 	| Receipt Number
	valueRegEx[10] = /^[0-9]{10,12}$/;																//11-13	| SEVIS Identification Number
	valueRegEx[11] = /[A-Z0-9,.\'\ \-]{1,40}/;														//1-40 	| Travel Document Number	
	valueRegEx[12] = /^[0-9]{12}$/;																	//12 	| USCIS Online Acct Numberâ 



	msgExitArray[0] = "Enter a 5 digit ZIP Code.";		
	msgExitArray[1] = "Enter a 9 digit Social Security Number.";
	msgExitArray[2] = "Enter a 9 digit Alien Registration Number.";
	msgExitArray[3] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: mm/dd/yyyy.";
	msgExitArray[4] = "Enter a valid 4 digit year.";
	msgExitArray[5] = "Enter only letters, numbers, space and hyphen.";
	msgExitArray[6] = "Enter a 12 character USCIS Online Account Number. Enter only numbers and letters.";	
	msgExitArray[7] = "Enter a 9 digit Individual Taxpayer Identification Number.";
	msgExitArray[8] = "Enter a 9 digit Federal Employer Identification Number.";
	msgExitArray[9] = "Enter an 11 character I-94 Arrival-Departure Record Number.";
	msgExitArray[10] = "Enter a six digit NAICS number.";
	msgExitArray[11] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: MM/DD/YYYY OR enter enter D/S for Duration of Status.";
	msgExitArray[12] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: MM/DD/YYYY OR if this date is the current date enter Present";
	msgExitArray[13] = "Enter the 13 digit Reciept Number."; 
	msgExitArray[14] = "Enter a 4 digit ZIP plus 4 extension.";
	msgExitArray[15] = "Enter a 13 digit New Commercial Enterprise (NCE) Identification Number.";
	msgExitArray[16] = "Enter a valid Passport Number.";
	msgExitArray[17] = "Enter a 10 to 12 digit Student and Exchange Visitor Information System (SEVIS) Number.";


	msgChangeArray[0] = "Enter only letters.";									///[^A-Za-z]/
	msgChangeArray[1] = "Enter only letters, and numbers.";						///[^A-Za-z0-9]/
	msgChangeArray[2] = "Enter only letters, numbers, and hyphens.";			///[^A-Za-z0-9\-]/
	msgChangeArray[3] = "Enter only letters, numbers, and periods.";			///[^A-Za-z0-9\.]/
	msgChangeArray[4] = "Enter only letters, numbers, and spaces.";				///[^A-Za-z0-9\ ]/
	msgChangeArray[5] = "Enter only letters, numbers, spaces, and hyphens.";	///[^A-Za-z0-9\-\ ]/
	msgChangeArray[6] = "Enter only letters, numbers, spaces, and slashes.";	///[^A-Za-z0-9\/ ]/ 
	msgChangeArray[7] = "Enter only letters, and spaces.";						///[^A-Za-z ]/
	msgChangeArray[8] = "Enter only letters, spaces, and hyphens.";				///[^A-Za-z\- ]/
	msgChangeArray[9] = "Enter only letters, spaces, and slashes.";				///[^A-Za-z\- \/]/
	msgChangeArray[10] = "Enter only letters, spaces, hyphens, and slashes.";	///[^A-Za-z\/\- ]/
	msgChangeArray[11] = "Enter only numbers 0 or 1.";							///[^0-1]/
	msgChangeArray[12] = "Enter only numbers.";									///[^0-9]/
	msgChangeArray[13] = "Enter only numbers, and periods.";					///[^0-9\.]/
	msgChangeArray[14] = "Enter only letters, numbers, period, comma, apostrophe, hyphen, ampersand and space.";	///[^A-Za-z0-9\.\,\'\-\&amp;\ ]/
	msgChangeArray[15] = "Enter only numbers and slashes";						///[^0-9\/]/
	msgChangeArray[16] = "Enter only letters, numbers, hyphens, spaces, and commas.";	///[^A-Za-z0-9\- ,]/
	msgChangeArray[17] = "Enter only letters, spaces, hyphens, slashes, periods and commas.";	///[^A-Za-z\-\/\.\, ]/
	msgChangeArray[18] = "Enter only numbers, slashes";							///[^0-9NnAa\/]/
	msgChangeArray[19] = "Enter only numbers 0 through 6";						///[^0-6]/
	msgChangeArray[20] = "Enter only letters, numbers, space, period, and slashes";		///[^A-Za-z0-9\ \.\/]/	
	msgChangeArray[21] = "Enter only letters, numbers, hyphen, @, underscore, period";	///[^A-Za-z0-9\@\_\.\-]/
	msgChangeArray[22] = "Enter only letters, numbers, spaces, hyphen, slash";	///[^A-Za-z0-9\ \-\/]/
	msgChangeArray[23] = "Enter only letters, numbers, hyphen, comma, apostrophe, and ampersands";	///[^a-zA-Z0-9\-\.\,\'\&]/
	msgChangeArray[24] = "Enter only numbers. If not applicable or unknown enter N/A or None.";	///[^0-9AaNnOoEe\/]/
	msgChangeArray[25] = "Enter only numbers and slashes or enter 'D/S'"; //[^0-9DdSs\/]/
	msgChangeArray[26] = "Enter only numbers and slashes or enter 'Present'";		

/*******************************************************************************
This function monitors key strokes for fields to restrict entry to specific
characters
*******************************************************************************/

function valKeyEntry(regexValue, msgValue, msgType) 
{
	var regex = getKeyRegEx(regexValue);	//Get the regular expression for the object keyboard entry.		
	var msgText = getMessage(msgValue, msgType); //Get the appropriate error message from the getMessage function	

	if(regex.test(xfa.event.change)) 
	{
  		xfa.event.change = "";
  		xfa.host.messageBox(msgText, "Field Validation Error", 0, 0);
	}
}

/*******************************************************************************
This function monitors key strokes for date fields to restrict entry to specific
characters and determine the correct number of characters has been entered <=10
*******************************************************************************/

function dateValKeyEntry(regexValue, msgValue, msgType) 
{
	var regex = getKeyRegEx(regexValue);	//Get the regular expression for the object keyboard entry.		
	var msgText = getMessage(msgValue, msgType); //Get the appropriate error message from the getMessage function	

	if(regex.test(xfa.event.change)) 
	{
  		xfa.event.change = "";
  		xfa.host.messageBox(msgText, "Date Field Validation Error", 0, 0);
	}
	else if (xfa.event.newText.length > 10)
	{
		xfa.event.change = "";		
	}	 
}

/********************************************************************************
Get the reg exp value. Return to the function
********************************************************************************/
function getKeyRegEx(regexValue)
{
	var RegExKey;

	RegExKey = keyRegEx[regexValue];
	return RegExKey;	
}

/********************************************************************************
Get the reg exp value. Return to the function
********************************************************************************/
function getValueRegEx(regexValue)
{
	var RegExValue;

	RegExValue = valueRegEx[regexValue];
	return RegExValue;	
}

/*******************************************************************************
This function creates the error messages for field validations.
When called the function returns the specified array value.
parameter msgValue - the array index value
var msgArray - Array of message values
var retMsg - The value in the array to be returned for display in error message
*******************************************************************************/
function getMessage(msgValue, msgType)
{
	var retMsg;

	if (msgType == "exit")
	{
	retMsg = msgExitArray[msgValue];	
	}
	else if (msgType == "change")
	{
	retMsg = msgChangeArray[msgValue];
	}
	return retMsg;	
}	


/*******************************************************************************
This function will validate the length or number of character entered.
Used for A- Number, US SSN, ZIP Code, etc.

*******************************************************************************/

function valLengthOnExit(objSOM, objValLen, msgValue, msgType)
{
	objSOM = xfa.resolveNode(objSOM);
	if (objSOM.rawValue == null || objSOM.rawValue == "")	//if the field is empty
	{
		// Do nothing
	}
	else
	{
		var msgText = getMessage(msgValue, msgType);	//Get the appropriate error message from the getMessage function	
		var objValueLen = objSOM.rawValue.length;
		if (objValueLen != objValLen)  //See if the entered value is equal in length to the total number of characters required by the field.
		{
			xfa.host.messageBox(msgText, "Validation Error", 0, 0); //post the error message, set the cursor back to the field.
			xfa.host.setFocus(objSOM);				
		}						
	}
	//return msgValue;
}

/*******************************************************************************
This function will check the field entered value against a pre-determined format
*******************************************************************************/
function valValueOnExit(objSOM, regexValue, msgValue, msgType)
{
	objSOM = xfa.resolveNode(objSOM);	// find the field to validate.
	var pattern = getValueRegEx(regexValue); // Get the regular expression to use
	//app.alert(pattern);
	var exitValue = objSOM.rawValue;  	// Get the raw value entered by the user.

	if (exitValue == null || exitValue == "") //Check if the field is empty or blank
	{
		//Do Nothing
	}	
	else
	{
		var msgText = getMessage(msgValue, msgType);
		if (pattern.test(exitValue) == false) // If the value is invalid, display an alert and clear the field.
		{
    		xfa.host.messageBox(msgText, "Validation Error", 0, 0); //post the error message, set the cursor back to the field.
    		xfa.host.setFocus(objSOM);    	
		}
	}	
}	

/*******************************************************************************
This function will check that a valid date was entered 
*******************************************************************************/
function dtValidation(objSOM, dtFuture, dateType)
{
	objSOM = xfa.resolveNode(objSOM);
	var validDate;

	validDate = checkDate(objSOM);

	if (objSOM.rawValue != "D/S" && objSOM.rawValue != "Present" && objSOM.rawValue != "PRESENT" && objSOM.rawValue != "present")
	{
		validDate = checkDate(objSOM);

		if (validDate == false)
		{
			if (dateType == "1")
			{
			xfa.host.messageBox("Date entered was not valid.\n\nThe Date must be a valid date, entered in the date format: MM/DD/YYYY\n\nRe-enter the Date", "Date Validation", 2, 0);
			xfa.host.setFocus(objSOM);
			}
			else
			{
			xfa.host.messageBox("Date entered was not valid.\n\nThe Date must be a valid date, entered in the date format: MM/YYYY\n\nRe-enter the Date", "Date Validation", 2, 0);
			xfa.host.setFocus(objSOM);
			}
		}	

		if (dtFuture == "1")
		{
			if (dateType == "1")
			{
			validDate = futureDate(objSOM);
			}
			else
			{
			validDate = futureDateMMYYYY(objSOM);
			}

			if (validDate == false)
			{
			xfa.host.messageBox("Date entered cannot be a future date\n\nRe-enter Date", "Future Date Validation", 2, 0);
			xfa.host.setFocus(objSOM);
			}
		}

		if (dtFuture == "2")
		{
			if (dateType == "1")
			{
			validDate = priorDate(objSOM);
			}
			else
			{
			validDate = priorDateMMYYYY(objSOM);
			}

			if (validDate == false)
			{
			xfa.host.messageBox("Date entered cannot be a prior date\n\nRe-enter Date", "Prior Date Validation", 2, 0);
			xfa.host.setFocus(objSOM);
			}

		}	
	}	
}


/***************************************************************
* Checks a date field for valid Date value
* @param - fldObject - date object to check
* @return - true (valid) or false (invalid)
****************************************************************/

function checkDate (objSOM)
{
	if (objSOM.rawValue != null && objSOM.rawValue != "")
	{
		var checkstr = "0123456789";
		var DateTemp = "";
		var blnError = false;
		var day;
		var month;
		var year;
		var leap = 0;
		var err = 0;		

		// To Retrieve display pattern use:
		var strPattern = objSOM.format.picture.value;

		/************************************************************
		Retrieve raw value - it can be either one of the following formats
		************************************************************/
		switch (strPattern)
		{
			case "date{MM/DD/YYYY}":
			//Verify that entered date is not longer than 10 characters.
			if (objSOM.formattedValue.length > 10)
			return false;	

			// Verify pattern is of form MM/DD/YYYY
			var arrPattern = strPattern.split("/");
			if (arrPattern.length != 3)
			return false;

			// Get date as formatted value
			var DateValue = objSOM.formattedValue;

			// Verify pattern is of form MM/DD/YYYY
			var arrDateVal = DateValue.split("/");

			if (arrDateVal.length != 3)
			return false;

			// Left-pad month and day if necessary
			for (i=0; i<arrDateVal.length; i++)
			{
				if (arrDateVal[i].length < 2)
				arrDateVal[1] = "0" + arrDateVal[i];
			}

			month = arrDateVal[0];
			day = arrDateVal[1];
			year = arrDateVal[2];

			// Validation
			if (year == 0)
			blnError = true;	

			if ((month < 1) || (month > 12))
			blnError = true;

			if (day < 1)
			blnError = true;

			if ((year % 4 == 0) || (year % 100 == 0) || (year % 400 == 0))
			leap = 1;

			if ((month == 2) && (leap == 1) && (day > 29))
			blnError = true;

			if ((month == 2) && (leap != 1) && (day > 28))
			blnError = true;			

			if ((day > 31) && ((month == "01") || (month == "03") || (month == "05") || (month == "07") || (month == "08") || (month == "10") || (month == "12")))
			blnError = true;

			if ((day > 30) && ((month == "04") || (month == "06") || (month == "09") || (month == "11")))
			blnError = true;

			if (blnError == false)
			{
				objSOM.rawValue = month + "/" + day + "/" + year;
				return true;
			}
			else
			{
				return false;
			}			
			break;

			case "date{MM/YYYY}":			
			//Verify that entered date is not longer than 10 characters.
			if (objSOM.formattedValue.length > 7)
			return false;	

			// Verify pattern is of form MM/YYYY
			var arrPattern = strPattern.split("/");
			if (arrPattern.length != 2)
			return false;

			// Get date as formatted value
			var DateValue = objSOM.formattedValue;

			// Verify pattern is of form MM/DD/YYYY
			var arrDateVal = DateValue.split("/");

			if (arrDateVal.length != 2)
			return false;

			// Left-pad month and day if necessary
			for (i=0; i<arrDateVal.length; i++)
			{
				if (arrDateVal[i].length < 2)
				arrDateVal[0] = "0" + arrDateVal[i];
			}

			month = arrDateVal[0];
			year = arrDateVal[1];

			// Validation
			if (year == 0)
			blnError = true;	

			if ((month < 1) || (month > 12))
			blnError = true;

			if (blnError == false)
			{
				objSOM.rawValue = month + "/" + year;
				return true;
			}
			else
			{
				return false;
			}

			break;

			default:
			// Invalid format - return false
			blnError = true;
			return false;
			break;
		}

	}
}

/****************************************************************
* Checks for a future date entered for MM/DD/YYYY
****************************************************************/
function futureDate(objSOM)
{
	if (objSOM.rawValue != null)
	{
		var today = new Date();
		var mm = String(today.getMonth() + 1);
		var dd = String(today.getDate());
		var yyyy = today.getFullYear();
		today = mm + "/" + dd + "/" + yyyy;

		var dateObject = util.scand("mm/dd/yyyy", objSOM.rawValue)
		var currentDate = util.scand("mm/dd/yyyy", today);

		if (dateObject > currentDate)
		{
		return false;
		}
	}	
}					

/****************************************************************
* Checks for a prior date entered for MM/DD/YYYY
****************************************************************/
function priorDate(objSOM)
{
	if (objSOM.rawValue != null)
	{
		var dateEnteredStr = objSOM.rawValue;

		if (dateEnteredStr)
		{
			var enteredDate = util.scand("mm/dd/yyyy", dateEnteredStr);
			var today = new Date();
			var mm = today.getMonth();
			var dd = today.getDate();
			var yyyy = today.getFullYear();
			if (mm < 10)
			{
				mm = "0" + mm;
			}
			if (dd < 10)
			{
				dd = "0" + dd;
			}		

			var currentDate = mm + "/" + dd + "/" + yyyy
			currentDate = util.scand("mm/dd/yyyy", currentDate);

			if (enteredDate < currentDate) 
			{
			return false;
			}
			else
			{
			return true;
			}		
		}
	}	
}	

/****************************************************************
* Checks for a future date entered for MM/YYYY
****************************************************************/
function futureDateMMYYYY(objSOM)
{
	if (objSOM.rawValue != null)
	{
		var today = new Date();
		var month = String(today.getMonth() + 1);

		if (month < 10)
		{
			month = "0" + month;
		}

		var yyyy = String(today.getFullYear());
		today = month + "/" + yyyy;

		var dateObject = util.scand("mm/yyyy", objSOM.rawValue)
		var currentDate = util.scand("mm/yyyy", today);		

		if (dateObject < currentDate)
		{
		return false;
		}
		else
		{
		return true;
		}
	}	
}	

/****************************************************************
* Checks for a prior date entered for MM/DD/YYYY
****************************************************************/
function priorDateMMYYYY(objSOM)
{
	if (objSOM.rawValue != null)
	{
		var dateEnteredStr = objSOM.rawValue;

		if (dateEnteredStr)
		{
			var enteredDate = util.scand("mm/yyyy", dateEnteredStr);
			var today = new Date();
			var currentDate = new Date(today.getFullYear(), today.getMonth(), 1)

			if (enteredDate < currentDate) 
			{
			return false;
			}
			else
			{
			return true;
			}		
		}
	}	
}	

/****************************************************************
* test for valid state of time
****************************************************************/
function tmValidation(tmObj)
{
	tmObj = xfa.resolveNode(tmObj);

	var validTime = checkTime(tmObj);

	if (validTime == false)
	{
	xfa.host.messageBox("Time entered was not valid.\n\nThe Time must be a valid date, entered in the time in the 24 Hour format: HH:MM\n\nRe-enter the Time", "Time Validation", 2, 0);
	xfa.host.setFocus(dtObj);
	}
}

/*****************************************************************
* Checks a time field for valid Time value
* @param - fldObject - time object to check
* @return - true (valid) or false (invalid)
*****************************************************************/

function checkTime (fldObject, time)
{
	if (fldObject.rawValue != null && fldObject.rawValue != "")
	{
		// To Retrieve display patter use:
		var strPattern = fldObject.format.picture.value;	

		// Get date as formatted value
		var TimeValue = fldObject.formattedValue;	

		// Verify pattern is of form HH:MM
		var arrTimeVal = TimeValue.split(":");

		if (arrTimeVal.length != 2)
		return false;

		if (arrTimeVal[0] > 24)
		return false;

		if (arrTimeVal[1] > 59)
		return false;		
	}	
}
